contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address target, uint amount, uint ownerWithdrawAmount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        address owner = c.owner();
        require(owner == address(this), "test contract is not owner");

        uint beforeBalance = address(c).balance;

        (bool sent, ) = target.call{value: amount}("");
        require(sent, "setup send failed");

        uint afterSendBalance = address(c).balance;
        require(afterSendBalance == beforeBalance + amount, "setup deposit failed");

        c.fallback{value: amount}();
        uint afterFallbackBalance = address(c).balance;
        require(afterFallbackBalance == afterSendBalance + amount, "fallback deposit failed");

        uint beforeNonOwnerWithdraw = address(c).balance;
        bool nonOwnerReverted;
        try c.withdraw(ownerWithdrawAmount) {
            nonOwnerReverted = false;
        } catch {
            nonOwnerReverted = true;
        }
        uint afterNonOwnerWithdraw = address(c).balance;

        bool nonOwnerWithdrawAllReverted;
        try c.withdrawAll() {
            nonOwnerWithdrawAllReverted = false;
        } catch {
            nonOwnerWithdrawAllReverted = true;
        }
        uint afterNonOwnerWithdrawAll = address(c).balance;

        bool nonOwnerSendReverted;
        try c.sendMoney(target, amount) {
            nonOwnerSendReverted = false;
        } catch {
            nonOwnerSendReverted = true;
        }
        uint afterNonOwnerSend = address(c).balance;

        assert(
            nonOwnerReverted &&
            nonOwnerWithdrawAllReverted &&
            nonOwnerSendReverted &&
            afterNonOwnerWithdraw == beforeNonOwnerWithdraw &&
            afterNonOwnerWithdrawAll == beforeNonOwnerWithdraw &&
            afterNonOwnerSend == beforeNonOwnerWithdraw
        );
    }
}

