contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address target, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        uint beforeDeposit = address(c).balance;
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");
        uint afterDeposit = address(c).balance;

        require(withdrawAmount <= afterDeposit, "withdraw exceeds C balance");

        uint beforeWithdraw = address(c).balance;
        c.withdraw(withdrawAmount);
        uint afterWithdraw = address(c).balance;

        assert(
            afterDeposit == beforeDeposit + depositAmount &&
            afterWithdraw == beforeWithdraw - withdrawAmount &&
            address(c).balance >= 0
        );
    }
}

