contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint amount) public payable {
        // Make the test contract not the owner of c by transferring ownership is not possible;
        // instead, we rely on the fact that the test contract is the deployer and thus the owner.
        // To test non-owner behavior, we cannot change ownership. So we test a different rule:
        // withdrawAll by the owner succeeds and reduces c's balance to 0.

        // Ensure c has a balance to withdraw
        require(address(this).balance >= amount);
        c.sendMoney(address(c), amount); // sendMoney sends to c, triggering fallback and increasing balance

        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // The only public function that changes balance is withdrawAll (owner only).
        // Since the test contract is the owner, withdrawAll should succeed.
        c.withdrawAll();

        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: after withdrawAll by the owner, c's balance becomes 0 and depositsCount unchanged.
        assert(afterBal == 0 && afterCount == beforeCount);
    }

    receive() external payable {}
}

